// explanation, card, question and homework here is the project's own original wording. Each lesson lists its aids
// (ids in the tool library), which are pinned to the prep and appear first in «مكتبة الوسائل الدراسية».
//
// Format per lesson: act (the interactive explanation, optional), aids, say (spoken explanation of the page), pts
// (four key points: the page lines and the board cards), ask (a thinking question), q (three choice questions
// [prompt, options, index of the right answer] and one open question), hw (instructions, two choice questions, one
// open question), sn (ready words for the board). Numbers are written with Latin digits and shown in Arabic-Indic.

const AR = '٠١٢٣٤٥٦٧٨٩';
/** Arabic-Indic digits and the Arabic thousands separator. */
export const arDigits = s => String(s).replace(/(\d),(?=\d{3})/g, '$1٬').replace(/\d/g, d => AR[d]);

